// Jetpack Compose output: one generated file with the mark geometry, the motion tracks and `BrandMark`.
// No dependency beyond Compose UI (Canvas + withFrameNanos); colours come from the generated `Tokens`.
import { LOGO_MOTION } from '../../src/motion.mjs';
import { IDS, geometry } from '../../src/marks.mjs';
import { n, nameOf } from './draw.mjs';
import { keys } from './motion.mjs';
import { EASE } from '../../src/motion.mjs';
import * as P from './path.mjs';

const f = (v) => `${n(v, 4)}f`;
const Case = (id) => id[0].toUpperCase() + id.slice(1);

/** Flat number list of a path: 0 x y = move, 1 x y = line, 2 x1 y1 x2 y2 x y = curve, 3 = close. */
function flat(d) {
  const out = [];
  for (const s of P.parse(d)) {
    if (s.c === 'M') out.push(0, s.x, s.y);
    else if (s.c === 'L') out.push(1, s.x, s.y);
    else if (s.c === 'C') out.push(2, s.x1, s.y1, s.x2, s.y2, s.x, s.y);
    else out.push(3);
  }
  return `floatArrayOf(${out.map(f).join(', ')})`;
}

function geometryLiteral(geo) {
  const lines = geo.lines.map((l) => `BrandLine(${l.role === 'b'}, ${flat(l.d)})`).join(',\n                ');
  const [cx, cy, r] = geo.dot;
  return `BrandGeometry(${f(geo.grid)}, ${f(geo.w)}, ${f(cx)}, ${f(cy)}, ${f(r)}, listOf(\n                ${lines},\n            ))`;
}

const track = (t) => (t ? `listOf(${keys(t).map((k) => `BrandKey(${f(k.t)}, ${f(k.v)}, ${EASE[k.ease].map(f).join(', ')})`).join(', ')})` : 'emptyList()');

/**
 * `Brand.kt` for one Android module family.
 * @param {string} pkg Kotlin package (the generated `Tokens` object lives in the same package)
 * @param {boolean} withLight the module also has `TokensLight` (phone apps); adds a `light` parameter
 */
export function kotlinBrand(pkg, withLight) {
  const M = LOGO_MOTION;
  const product = (id) => `Tokens.product${Case(id)}`;
  const productLight = (id) => `TokensLight.product${Case(id)}`;
  const color = (pick) =>
    IDS.map((id) => {
      const p = pick(id);
      return `            BrandProduct.${Case(id)} -> ${withLight ? `if (light) ${productLight(p)} else ${product(p)}` : product(p)}`;
    }).join('\n');
  const anim = (name) => {
    const a = M[name];
    return `            BrandAnimation.${Case(name)} -> BrandTracks(${a.duration}, ${Boolean(a.loop)}, ${f(a.lineSpread ?? 0)}, ${track(a.trimStart)}, ${track(a.lineOpacity)}, ${track(a.dotScale)}, ${track(a.shakeX)})`;
  };
  const lightParam = withLight ? '\n    light: Boolean = false,' : '';
  const lightDoc = withLight ? '\n * @param light draw for a light surface (darker product colours, dark signal).' : '';
  const lightArg = withLight ? ', light' : '';
  const signal = withLight ? 'if (light) TokensLight.foreground else Tokens.foreground' : 'Tokens.foreground';
  return `// GENERATED by brand/scripts/build.mjs from brand/src/marks.mjs and brand/src/motion.mjs. Do not edit.
package ${pkg}

import android.provider.Settings
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.aspectRatio
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableFloatStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberUpdatedState
import androidx.compose.runtime.setValue
import androidx.compose.runtime.withFrameNanos
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.PathMeasure
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.semantics.Role
import androidx.compose.ui.semantics.clearAndSetSemantics
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.role
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.unit.dp

/** The MixAI family mark ([Mark]) and the eight product glyphs. [label] is read by assistive technology. */
enum class BrandProduct(val label: String) {
${IDS.map((id) => `    ${Case(id)}(${JSON.stringify(nameOf(id))}),`).join('\n')}
}

/** Logo animations. Each one starts and ends on the static mark. */
enum class BrandAnimation { Intro, Loading, Success, Error }

/** One stroked line. [path] is a flat list: 0 x y = move, 1 x y = line, 2 x1 y1 x2 y2 x y = curve, 3 = close. */
class BrandLine(val secondStream: Boolean, val path: FloatArray)

/** A mark on its grid: stroked lines (the sources) and one filled dot (the signal). */
class BrandGeometry(val grid: Float, val stroke: Float, val dotX: Float, val dotY: Float, val dotR: Float, val lines: List<BrandLine>)

/** One keyframe: time 0..1, value, cubic-bezier easing into this key. */
internal class BrandKey(val t: Float, val v: Float, val x1: Float, val y1: Float, val x2: Float, val y2: Float)

/** Keyframe tracks of one animation; an empty track is not animated. The last line starts [lineSpread] late. */
internal class BrandTracks(
    val durationMs: Int,
    val loops: Boolean,
    val lineSpread: Float,
    val trimStart: List<BrandKey>,
    val lineOpacity: List<BrandKey>,
    val dotScale: List<BrandKey>,
    val shakeX: List<BrandKey>,
)

object Brand {
    /** Press feedback of a tappable mark. */
    const val PRESS_SCALE = ${f(M.press.scale)}
    const val PRESS_MS = ${M.press.duration}

    /** Splash to first screen. */
    const val MORPH_MS = ${M.morph.duration}

    /** Total length of the intro (last line included). */
    const val INTRO_MS = ${Math.round(M.intro.duration * (1 + M.intro.lineSpread))}

    /** Geometry for sizes above 16 dp. */
    fun geometry(product: BrandProduct): BrandGeometry =
        when (product) {
${IDS.map((id) => `            BrandProduct.${Case(id)} -> ${geometryLiteral(geometry(id).master)}`).join('\n')}
        }

    /** Geometry drawn for 16 dp and below. */
    fun microGeometry(product: BrandProduct): BrandGeometry =
        when (product) {
${IDS.map((id) => `            BrandProduct.${Case(id)} -> ${geometryLiteral(geometry(id).micro)}`).join('\n')}
        }

    internal fun tracks(animation: BrandAnimation): BrandTracks =
        when (animation) {
${['intro', 'loading', 'success', 'error'].map(anim).join('\n')}
        }

    /** Colour of the lines (the first stream of the family mark). */
    fun streamA(product: BrandProduct${withLight ? ', light: Boolean = false' : ''}): Color =
        when (product) {
${color((id) => (id === 'mark' ? 'tv' : id))}
        }

    /** Colour of the second stream (differs from [streamA] only for the family mark). */
    fun streamB(product: BrandProduct${withLight ? ', light: Boolean = false' : ''}): Color =
        when (product) {
${color((id) => (id === 'mark' ? 'music' : id))}
        }

    /** Value of a track at [time] (0..1); an empty track returns [rest]. */
    internal fun value(keys: List<BrandKey>, time: Float, rest: Float): Float {
        if (keys.isEmpty()) return rest
        if (time <= keys.first().t) return keys.first().v
        if (time >= keys.last().t) return keys.last().v
        for (i in 1 until keys.size) {
            val b = keys[i]
            if (time > b.t) continue
            val a = keys[i - 1]
            return a.v + (b.v - a.v) * ease((time - a.t) / (b.t - a.t), b.x1, b.y1, b.x2, b.y2)
        }
        return keys.last().v
    }

    /** cubic-bezier(x1, y1, x2, y2) evaluated at [x]. */
    internal fun ease(x: Float, x1: Float, y1: Float, x2: Float, y2: Float): Float {
        if (x1 == y1 && x2 == y2) return x
        fun curve(t: Float, p1: Float, p2: Float): Float {
            val u = 1f - t
            return 3f * u * u * t * p1 + 3f * u * t * t * p2 + t * t * t
        }
        var lo = 0f
        var hi = 1f
        var t = x
        repeat(24) {
            val at = curve(t, x1, x2)
            if (kotlin.math.abs(at - x) < 0.0005f) return curve(t, y1, y2)
            if (at < x) lo = t else hi = t
            t = (lo + hi) / 2f
        }
        return curve(t, y1, y2)
    }

    internal fun path(flat: FloatArray): Path {
        val p = Path()
        var i = 0
        while (i < flat.size) {
            when (flat[i].toInt()) {
                0 -> { p.moveTo(flat[i + 1], flat[i + 2]); i += 3 }
                1 -> { p.lineTo(flat[i + 1], flat[i + 2]); i += 3 }
                2 -> { p.cubicTo(flat[i + 1], flat[i + 2], flat[i + 3], flat[i + 4], flat[i + 5], flat[i + 6]); i += 7 }
                else -> { p.close(); i += 1 }
            }
        }
        return p
    }
}

/**
 * The MixAI mark or a product glyph, drawn as vectors. Square: give it a size through [modifier].
 *
 * [animation] plays from the first frame. With system animations off (animator duration scale 0) or with
 * \`animation == null\` it draws the static mark; a loading state must then show a text status next to it.
 *
 * @param tint one colour for the whole mark (lines and dot); null = brand colours.
 * @param decorative hide from assistive technology (use when the name is written next to it).
 * @param onFinished called once when a non-looping animation ends (at once when nothing is animated).${lightDoc}
 */
@Composable
fun BrandMark(
    product: BrandProduct = BrandProduct.Mark,
    modifier: Modifier = Modifier,
    animation: BrandAnimation? = null,
    tint: Color? = null,
    decorative: Boolean = false,${lightParam}
    onFinished: (() -> Unit)? = null,
) {
    val context = LocalContext.current
    val still = remember(context) { Settings.Global.getFloat(context.contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f }
    val tracks = remember(animation, still) { if (animation != null && !still) Brand.tracks(animation) else null }
    var elapsedMs by remember(animation) { mutableFloatStateOf(0f) }
    val finished by rememberUpdatedState(onFinished)
    LaunchedEffect(tracks) {
        if (tracks != null) {
            val total = tracks.durationMs * (1f + tracks.lineSpread)
            val start = withFrameNanos { it }
            while (tracks.loops || elapsedMs < total) {
                elapsedMs = (withFrameNanos { it } - start) / 1_000_000f
            }
        }
        finished?.invoke()
    }
    val master = remember(product) { Brand.geometry(product) }
    val micro = remember(product) { Brand.microGeometry(product) }
    val masterPaths = remember(master) { master.lines.map { Brand.path(it.path) } }
    val microPaths = remember(micro) { micro.lines.map { Brand.path(it.path) } }
    val measure = remember { PathMeasure() }
    val segment = remember { Path() }
    val a = tint ?: Brand.streamA(product${lightArg})
    val b = tint ?: Brand.streamB(product${lightArg})
    val signal = tint ?: (${signal})
    val semantics = if (decorative) Modifier.clearAndSetSemantics { } else Modifier.semantics { contentDescription = product.label; role = Role.Image }
    Canvas(modifier.aspectRatio(1f).then(semantics)) {
        val side = size.minDimension
        val small = side <= 16.dp.toPx()
        val geo = if (small) micro else master
        val paths = if (small) microPaths else masterPaths
        val unit = side / geo.grid
        // time is read here, so a frame only redraws (no recomposition)
        fun progress(delay: Float): Float {
            val t = tracks ?: return 0f
            val raw = elapsedMs / t.durationMs - delay
            return if (t.loops) (if (raw < 0f) 0f else raw % 1f) else raw.coerceIn(0f, 1f)
        }
        val shake = if (tracks != null) Brand.value(tracks.shakeX, progress(0f), 0f) * geo.grid / 48f else 0f
        translate((size.width - side) / 2f + shake * unit, (size.height - side) / 2f) {
            scale(unit, unit, pivot = Offset.Zero) {
                val style = Stroke(width = geo.stroke, cap = StrokeCap.Round, join = StrokeJoin.Round)
                val last = geo.lines.size - 1
                geo.lines.forEachIndexed { index, line ->
                    var trim = 0f
                    var opacity = 1f
                    if (tracks != null) {
                        val t = progress((if (last > 0) index.toFloat() / last else 0f) * tracks.lineSpread)
                        trim = Brand.value(tracks.trimStart, t, 0f)
                        opacity = Brand.value(tracks.lineOpacity, t, 1f)
                    }
                    if (trim < 0.999f) {
                        val base = if (line.secondStream) b else a
                        val drawn =
                            if (trim > 0f) {
                                measure.setPath(paths[index], false)
                                segment.reset()
                                measure.getSegment(measure.length * trim, measure.length, segment, true)
                                segment
                            } else {
                                paths[index]
                            }
                        drawPath(drawn, base.copy(alpha = base.alpha * opacity), style = style)
                    }
                }
                val dot = if (tracks != null) Brand.value(tracks.dotScale, progress(0f), 1f) else 1f
                drawCircle(signal, radius = geo.dotR * dot, center = Offset(geo.dotX, geo.dotY))
            }
        }
    }
}
`;
}
